contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address jojoTeam_, string calldata description_) public payable {
        require(address(this).balance >= 0, "insufficient balance");

        (bool ok, bytes memory data) = address(c).call(
            abi.encodeWithSignature("newEmergencyOracle(string)", description_)
        );
        require(ok, "newEmergencyOracle failed");

        address newOracle = abi.decode(data, (address));

        require(jojoTeam_ != address(0), "jojoTeam_ must be nonzero");
        c.newEmergencyOracle(description_);

        (bool okOwner, bytes memory ownerData) = newOracle.staticcall(
            abi.encodeWithSignature("owner()")
        );
        require(okOwner, "owner() failed");
        address oracleOwner = abi.decode(ownerData, (address));

        (bool okDesc, bytes memory descData) = newOracle.staticcall(
            abi.encodeWithSignature("description()")
        );
        require(okDesc, "description() failed");
        string memory oracleDescription = abi.decode(descData, (string));

        assert(oracleOwner == address(c) && keccak256(bytes(oracleDescription)) == keccak256(bytes(description_)));
    }

    receive() external payable {}
}

