contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description_, uint256 amount) public payable {
        require(amount == 0, "amount must be zero");

        bool reverted;
        uint256 balBefore = address(this).balance;
        try c.newEmergencyOracle{value: amount}(description_) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = address(this).balance;

        assert(reverted || balAfter == balBefore);
    }

    receive() external payable {}
}

